svg.script:
(() => {
  'use strict';

  const status = document.getElementById('canary-status');
  const correlation = new URLSearchParams(window.location.search);
  const payloadId = correlation.get('payload_id');
  const marker = correlation.get('marker');
  const postJson = (path, body) => fetch(path, {
    method: 'POST',
    credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(body)
  }).then(async (response) => {
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error('local evidence rejected');
    return result;
  });

  if (!payloadId || !marker) {
    status.textContent = 'Canary blocked: correlation metadata is absent.';
    return;
  }

  postJson('/api/lab-events', {
    type: 'PAYLOAD_EXECUTED',
    payload_id: payloadId,
    marker
  })
    .then(() => postJson('/api/send_message', {
        text: '🐑 Safe canary: forged action demonstrated',
        payload_id: payloadId,
        marker,
        lab_event: 'FORGED_ACTION'
      }))
    .then((result) => {
      status.textContent = result.ignored
        ? 'Canary ignored: open the intended victim session.'
        : 'Local evidence recorded.';
    })
    .catch(() => {
      status.textContent = 'Canary blocked or evidence endpoint unavailable.';
    });
})();
